{"function":"() => {
const deep = (root, sel, acc=[]) => { root.querySelectorAll(sel).forEach(e=>acc.push(e)); root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) deep(e.shadowRoot, sel, acc)}); return acc; };
const out = {};
out.imgs = deep(document,'img').map(i=>({alt:i.getAttribute('alt'), src:i.getAttribute('src'), host: i.getRootNode().host?.tagName}));
const eye = document.querySelector('tr:nth-child(1) > td:nth-child(9) br-button[icon="eye"]');
out.eye = eye?.outerHTML.slice(0,400);
out.eyeParent = eye?.parentElement?.outerHTML.slice(0,300);
const att = document.querySelector('tr:nth-child(1) > td:nth-child(9) .d-flex > div:nth-child(1)');
out.att = att?.outerHTML.slice(0,500);
const av = deep(document, 'button').find(b=>b.getAttribute('aria-label')==='Avatar com dropdown' || b.textContent.includes('Olá'));
out.av = av ? av.outerHTML.slice(0,600) : null;
out.menuBtn = deep(document,'button').filter(b=>b.getAttribute('aria-label')==='Menu').map(b=>b.outerHTML.slice(0,300));
out.dateWrap = document.querySelector('br-input:nth-child(2)')?.parentElement?.parentElement?.outerHTML.slice(0,800);
out.th1 = document.querySelector('th:nth-child(1)')?.outerHTML;
out.thead = [...document.querySelectorAll('thead th')].map(t=>({txt:t.textContent.trim(), scope:t.getAttribute('scope'), aria: t.getAttribute('aria-sort'), html:t.innerHTML.slice(0,150)}));
out.caption = document.querySelector('table caption')?.textContent || null;
out.tableLabel = document.querySelector('table')?.getAttribute('aria-label');
return out;
}"}

